from dataclasses import dataclass
from .validation import one, many
from .grants import issue, require

@dataclass(frozen=True)
class Plan:
    grant: object
    names: tuple[str, ...]

def resolve_one(request, catalog):
    supplied = one(request.arguments)
    target = catalog.canonical(supplied)
    grant = issue(request.identity, (target,))
    return Plan(grant, (target,))

def resolve_batch(request, catalog):
    supplied = many(request.arguments)
    targets = catalog.canonical_many(supplied)
    grant = issue(request.identity, targets)
    return Plan(grant, targets)

def resolve_metadata(request, catalog):
    target = catalog.canonical(one(request.arguments))
    require(request.identity, target)
    return target

from .errors import AccessDenied

def execute(plan, store):
    if plan.grant.operation != "read":
        raise AccessDenied("read grant required")
    return store.fetch_many(plan.names)

"""Retained for offline migration readers; not registered by bootstrap."""
from .errors import AccessDenied

def require_operator(identity):
    if identity.role != "owner":
        raise AccessDenied("owner required")

def load_manifest(identity, manifest):
    require_operator(identity)
    if manifest.get("version") != 1:
        raise ValueError("unsupported manifest")
    return tuple(manifest.get("records", ()))

def emit_manifest(identity, records):
    require_operator(identity)
    return {"version": 1, "records": list(records)}

